    sheetName: 'TourBook',
    fallbackTitle: 'TourBook',
    fallbackTour: 'Untitled Tour',
    generatedBy: 'Generated by Touracle',
    sourceFile: 'Source file',
    weatherMode: 'Weather Mode',
